#: transaction, not on a half-done one.
SHELF_RULE_SQL = """
CREATE OR REPLACE FUNCTION inventory_shelf_rule_check(p_item uuid, p_location uuid)
RETURNS void LANGUAGE plpgsql AS $$
DECLARE
    shelved numeric;
    held numeric;
BEGIN
    SELECT COALESCE(SUM(quantity), 0) INTO shelved
      FROM inventory_spotstock WHERE item_id = p_item AND location_id = p_location;
    IF shelved <= 0 THEN
        RETURN;
    END IF;
    SELECT quantity INTO held FROM inventory_locationstock
     WHERE item_id = p_item AND location_id = p_location FOR UPDATE;
    IF held IS NULL THEN
        held := 0;
    END IF;
    IF shelved > held THEN
        RAISE EXCEPTION 'shelf_stock_exceeds_location: shelves hold % but the location has %', shelved, held;
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION inventory_spotstock_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    PERFORM inventory_shelf_rule_check(NEW.item_id, NEW.location_id);
    RETURN NULL;
END;
$$;

CREATE OR REPLACE FUNCTION inventory_locationstock_shelf_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    PERFORM inventory_shelf_rule_check(OLD.item_id, OLD.location_id);
    RETURN NULL;
END;
$$;

CREATE CONSTRAINT TRIGGER inventory_spotstock_guard
    AFTER INSERT OR UPDATE ON inventory_spotstock
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION inventory_spotstock_guard();

CREATE CONSTRAINT TRIGGER inventory_locationstock_shelf_guard_update
    AFTER UPDATE ON inventory_locationstock
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW WHEN (NEW.quantity < OLD.quantity)
    EXECUTE FUNCTION inventory_locationstock_shelf_guard();

CREATE CONSTRAINT TRIGGER inventory_locationstock_shelf_guard_delete
    AFTER DELETE ON inventory_locationstock
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION inventory_locationstock_shelf_guard();
"""

